# can be serialised into a NLMSG_ERROR
class NetlinkError(Exception):
    def __init__(self, errno, msg=None):
        self.errno = errno
        self.msg = msg

    def to_nlmsg(self, seq=0):
        resp = netlink.nlmsgerr()
        resp['header']['sequence_number'] = seq
        resp['header']['pid'] = 0
        resp['header']['type'] = netlink.NLMSG_ERROR
        resp['error'] = -self.errno
        if self.msg:
            resp['attrs'] = [['NLMSGERR_ATTR_MSG', self.msg]]
        return resp


class PhysicalBinding(enum.Enum):
    UNSPEC = 0x00
    SMBUS = 0x01
    PCIE_VDM = 0x02
    USB = 0x03
    KCS = 0x04
    SERIAL = 0x05
    I3C = 0x06
    MMBI = 0x07
    PCC = 0x08
    UCIE = 0x09
    VENDOR = 0xFF


class System:
    class Interface:
        """Interface constructor.

        Initial mtu is set to max_mtu.
        """

        def __init__(
            self,
            name,
            ifindex,
            net,
            lladdr,
            min_mtu,
            max_mtu,
            up=False,
            phys_binding=PhysicalBinding.UNSPEC,
        ):
            self.name = name
            self.ifindex = ifindex
            self.net = net
            self.lladdr = lladdr
            self.min_mtu = min_mtu
            self.max_mtu = max_mtu
            self.mtu = max_mtu
            self.up = up
            self.phys_binding = phys_binding
            self.sysfs_path = '/devices/virtual/' + name

        def __str__(self):
            lladdrstr = ':'.join('%02x' % b for b in self.lladdr)
            return (
                f"{self.name}: "
                f"net {self.net} "
                f"lladdr {lladdrstr} "
                f"binding {self.phys_binding.name}"
            )

    class Address:
        def __init__(self, iface, eid):
            self.iface = iface
            self.eid = eid

        def __str__(self):
            return f"{self.eid} ({self.iface.name})"

    class Neighbour:
        def __init__(self, iface, lladdr, eid):
            self.iface = iface
            self.lladdr = lladdr
            self.eid = eid

        def __str__(self):
            lladdrstr = ':'.join('%02x' % b for b in self.lladdr)
            return f"{self.eid} -> {lladdrstr} {self.iface.name}"

    class Route:
        def __init__(self, start_eid, extent_eid, iface=None, gw=None, mtu=0):
            if (iface is None) and (gw is None):
                raise ValueError("neither interface or gateway are set")
            elif (iface is not None) and (gw is not None):
                raise ValueError("both interface and gateway are set")

            if type(gw) is int:
                # use default net
                gw = (1, gw)
            elif type(gw) in [tuple, list] and len(gw) == 2:
                gw = tuple(gw)
                if gw[0] == 0:
                    gw = (1, gw[1])
            elif gw is not None:
                raise ValueError("gateway should be a 2-tuple or int")

            self.iface = iface
            self.gw = gw
            self.start_eid = start_eid
            self.end_eid = start_eid + extent_eid
            self.mtu = mtu

        def net(self):
            if self.gw is not None:
                return self.gw[0]
            elif self.iface is not None:
                return self.iface.net
            raise ValueError("no gw or iface")

        def __str__(self):
            s = f"{self.start_eid}-{self.end_eid} -> "
            if self.iface:
                s += f"iface {self.iface.name} "
            else:
                (net, eid) = self.gw
                s += f"gw {net},{eid} "
            s += f"mtu {self.mtu}"
            return s

    def __init__(self):
        self.interfaces = []
        self.addresses = []
        self.neighbours = []
        self.routes = []
        self.nl = None

    async def add_route(self, route):
        self.routes.append(route)
        if self.nl:
            await self.nl.notify_newroute(route)

    async def del_route(self, route):
        route = self.lookup_route_exact(
            route.net(), route.start_eid, route.end_eid
        )
        if not route:
            raise NetlinkError(errno.ENOENT)

        self.routes.remove(route)
        if self.nl:
            await self.nl.notify_delroute(route)

    async def add_interface(self, iface):
        self.interfaces.append(iface)
        await self.notify_interface(iface)

    async def notify_interface(self, iface):
        if self.nl:
            await self.nl.notify_newlink(iface)

    async def del_interface(self, iface):
        routes = list(filter(lambda x: x.iface == iface, self.routes))
        for x in routes:
            await self.del_route(x)
        neighbours = list(filter(lambda x: x.iface == iface, self.neighbours))
        for x in neighbours:
            await self.del_neighbour(x)
        addresses = list(filter(lambda x: x.iface == iface, self.addresses))
        for x in addresses:
            await self.del_address(x)

        self.interfaces.remove(iface)
        if self.nl:
            await self.nl.notify_dellink(iface)

    async def add_address(self, address):
        self.addresses.append(address)
        if self.nl:
            await self.nl.notify_newaddr(address)

    async def del_address(self, address):
        addr = self.lookup_address(address.iface, address.eid)
        if not addr:
            raise NetlinkError(errno.ENOENT)
        self.addresses.remove(addr)
        if self.nl:
            await self.nl.notify_deladdr(address)

    async def add_neighbour(self, neigh):
        if self.lookup_neighbour(neigh.iface, neigh.eid):
            raise NetlinkError(errno.EEXIST)
        self.neighbours.append(neigh)
        if self.nl:
            await self.nl.notify_newneigh(neigh)

    async def del_neighbour(self, neigh):
        neigh = self.lookup_neighbour(neigh.iface, neigh.eid)
        if not neigh:
            raise NetlinkError(errno.ENOENT)
        self.neighbours.remove(neigh)
        if self.nl:
            await self.nl.notify_delneigh(neigh)

    def find_interface_by_ifindex(self, ifindex):
        for i in self.interfaces:
            if i.ifindex == ifindex:
                return i
        return None

    def find_interface_by_name(self, name):
        for i in self.interfaces:
            if i.name == name:
                return i
        return None

    def lookup_route(self, net, eid):
        for rt in self.routes:
            eid_range = range(rt.start_eid, rt.end_eid + 1)
            if net in (0, rt.net()) and eid in eid_range:
                return rt
        return None

    def lookup_route_exact(self, net, start_eid, end_eid):
        for rt in self.routes:
            if (
                rt.net() == net
                and rt.start_eid == start_eid
                and rt.end_eid == end_eid
            ):
                return rt
        return None

    def lookup_neighbour(self, iface, eid):
        for neighbour in self.neighbours:
            if neighbour.iface == iface and neighbour.eid == eid:
                return neighbour
        return None

    def lookup_address(self, iface, eid):
        for address in self.addresses:
            if address.iface == iface and address.eid == eid:
                return address
        return None

    def find_endpoint(self, addr):
        iface = None
        lladdr = None
        if addr.is_ext:
            iface = self.find_interface_by_ifindex(addr.ifindex)
            lladdr = addr.lladdr
        else:
            route = self.lookup_route(addr.net, addr.eid)
            if route is None:
                return None
            if route.gw is not None:
                # In case of gateway routes, we need not have neighbours
                # for the gated endpoints, but only need to find the
                # gateway's physical address
                # TODO: handle recursive gateway and alternate routes
                # for downstream endpoints
                gw_net, gw_eid = route.gw
                gw_route = self.lookup_route(gw_net, gw_eid)
                if gw_route is None or gw_route.iface is None:
                    return None
                iface = gw_route.iface
                neigh = self.lookup_neighbour(gw_route.iface, gw_eid)
                lladdr = neigh.lladdr if neigh else bytes()
            else:
                iface = route.iface
                neigh = self.lookup_neighbour(route.iface, addr.eid)
                lladdr = neigh.lladdr if neigh else bytes()

        if iface is None or lladdr is None:
            return None

        return iface, lladdr

    def lookup_link_path(self, ifname: str):
        iface = self.find_interface_by_name(ifname)
        if iface is None:
            return None
        return iface.sysfs_path

    def dump(self):
        print("system:")
        if self.interfaces:
            print(" interfaces:")
            for i in self.interfaces:
                print(f"  {i}")
        if self.addresses:
            print(" addresses:")
            for a in self.addresses:
                print(f"  {a}")
        if self.routes:
            print(" routes:")
            for r in self.routes:
                print(f"  {r}")
        if self.neighbours:
            print(" neighbours:")
            for n in self.neighbours:
                print(f"  {n}")


class MCTPCommand:
    def __init__(self):
        self.send_channel, self.receive_channel = trio.open_memory_channel(0)

    async def complete(self, data):
        async with self.send_channel as chan:
            await chan.send(data)

    async def wait(self):
        async with self.receive_channel as chan:
            return await chan.receive()


class MCTPControlCommand(MCTPCommand):
    MSGTYPE = 0

    def __init__(self, rq, iid, cmd, data=bytes()):
        super().__init__()
        self.rq = rq
        self.iid = iid
        self.cmd = cmd
        self.data = data

    def to_buf(self):
        flags = self.iid
        if self.rq:
            flags = flags | 0x80
        return bytes([flags, self.cmd]) + self.data


class VDMType:
    TYPE_PCI = 0x7E
    TYPE_IANA = 0x7F
    FORMAT_PCI = 0
    FORMAT_IANA = 1
    # type to (name, format, type_size)
    type_map = {
        TYPE_PCI: ("PCI", FORMAT_PCI, 2),
        TYPE_IANA: ("IANA", FORMAT_IANA, 4),
    }
    # format to (type, dbus type)
    fmt_map = {
        FORMAT_PCI: (TYPE_PCI, 'q'),
        FORMAT_IANA: (TYPE_IANA, 'u'),
    }

    def __init__(self, msgtype, vdmtype, subtype=0):
        self.msgtype = msgtype
        self.vdmtype = vdmtype
        self.subtype = subtype

    def __repr__(self):
        (name, _, _) = self.type_map.get(self.msgtype)
        return f"<VDMType {name}: {self.vdmtype:x} {self.subtype:x}>"

    def _key(self):
        return (self.msgtype, self.vdmtype, self.subtype)

    def __eq__(self, value):
        return self._key() == value._key()

    def __hash__(self):
        return hash(self._key())

    def format(self):
        """Convert to the Get Vendor Defined Message Support response format"""
        (_, vid_fmt, vid_size) = self.type_map.get(self.msgtype)

        return (
            vid_fmt.to_bytes(1)
            + self.vdmtype.to_bytes(vid_size, 'big')
            + self.subtype.to_bytes(2, 'big')
        )

    @classmethod
    def parse_dbus(cls, dbus_res):
        """Convert from a dbus GetVendorDefinedMessageTypes reply"""
        types = []
        for t in dbus_res:
            fmt, var, subtype = t
            (msgtype, dbus_type) = cls.fmt_map.get(fmt)
            assert var.signature == dbus_type
            types.append(cls(msgtype, var.value, subtype))
        return types


class Endpoint:
    def __init__(
        self, iface, lladdr, ep_uuid=None, eid=0, types=None, vdm_msg_types=None
    ):
        self.iface = iface
        self.lladdr = lladdr
        self.uuid = ep_uuid or uuid.uuid1()
        self.eid = eid
        self.vdm_msg_types = vdm_msg_types or []
        vdm_set = set([t.msgtype for t in self.vdm_msg_types])
        if types is None:
            self.types = [0] + list(vdm_set)
        else:
            self.types = types
        self.bridged_eps = []
        self.allocated_pool = None  # or (start, size)
        # Routing Information Updates (cmd 0x09) received from mctpd. Each item
        # is the first_eid carried by the update; used by bridge-forwarding
        # tests to assert whether mctpd forwarded an update to this endpoint.
        self.routing_info_updates = []

        # keyed by (type, type-specific-instance)
        self.commands = {}

    def __str__(self):
        return f"uuid {self.uuid} lladdr {self.lladdr}, eid {self.eid}"

    def reset(self):
        self.eid = 0

    def add_bridged_ep(self, ep):
        self.bridged_eps.append(ep)

    async def handle_mctp_message(self, sock, addr, data):
        # for us?
        if addr.eid == 0 or addr.eid == self.eid:
            if addr.type == 0:
                await self.handle_mctp_control(sock, addr, data)
            else:
                print(f"unknown MCTP message type {addr.type}")
        else:
            for br_ep in self.bridged_eps:
                if addr.eid == br_ep.eid:
                    return await br_ep.handle_mctp_message(sock, addr, data)

    async def handle_mctp_control(self, sock, addr, data):
        flags, opcode = data[0:2]
        rq = flags & 0x80
        iid = flags & 0x1F

        if not rq:
            cmd = self.commands.pop((0, iid), None)
            assert cmd is not None, "unexpected response?"

            await cmd.complete(data)

        else:
            raddr = MCTPSockAddr.for_ep_resp(self, addr, sock.addr_ext)
            # Use IID from request, zero Rq and D bits
            hdr = [iid, opcode]

            if opcode == 1:
                # Set Endpoint ID
                (op, eid) = data[2:]
                self.eid = eid
                pool_size = len(self.bridged_eps)
                alloc_status = 0x00
                # request a pool if we have one
                if pool_size:
                    alloc_status |= 0x01
                data = bytes(hdr + [0x00, alloc_status, self.eid, pool_size])
                await sock.send(raddr, data)

            elif opcode == 2:
                # Get Endpoint ID
                ep_type = 0
                if len(self.bridged_eps) > 0:
                    ep_type = 0x1 << 4
                data = bytes(hdr + [0x00, self.eid, ep_type, 0x00])
                await sock.send(raddr, data)

            elif opcode == 3:
                # Get Endpoint UUID
                data = bytes(hdr + [0x00]) + self.uuid.bytes
                await sock.send(raddr, data)

            elif opcode == 5:
                # Get Message Type Support
                types = self.types
                data = bytes(hdr + [0x00, len(types)] + types)
                await sock.send(raddr, data)

            elif opcode == 9:
                # Routing Information Update (DSP0236). Record the advertised
                # first_eid so tests can assert whether mctpd forwarded this
                # update to us, then ack with success.
                # Wire layout after [flags, opcode]:
                #   [number_of_entries, entry_type, eid_range, first_eid, ...]
                first_eid = data[5] if len(data) > 5 else None
                self.routing_info_updates.append(first_eid)
                data = bytes(hdr + [0x00])
                await sock.send(raddr, data)

            elif opcode == 0x0A:
                # Get Routing Table Entries (DSP0236) — bridge coverage for mctpd
                entries_blob = b""
                for br in self.bridged_eps:
                    se = br.eid
                    entries_blob += bytes([1, se, 0, 0, 0, 0])
                num = len(self.bridged_eps)
                data = bytes(hdr + [0x00, 0xFF, num]) + entries_blob
                await sock.send(raddr, data)

            elif opcode == 6:
                # Get Vendor Defined Message Support
                vdm_types = self.vdm_msg_types
                n_vdm_types = len(vdm_types)
                selector = data[2]
                if selector >= n_vdm_types:
                    await sock.send(raddr, bytes(hdr + [0x02]))
                    return
                vdm_data = vdm_types[selector].format()
                next_selector = (
                    0xFF if selector == (n_vdm_types - 1) else selector + 1
                )
                resp = bytes(hdr + [0x00, next_selector]) + vdm_data
                await sock.send(raddr, resp)

            elif opcode == 8:
                # Allocate Endpoint IDs
                (_, _, _, pool_size, pool_start) = data
                alloc_status = 0x00
                if self.allocated_pool is not None:
                    alloc_status = 0x01
                else:
                    self.allocated_pool = (pool_start, pool_size)
                    # Assign sequential EIDs starting from pool_start
                    for n, ep in enumerate(self.bridged_eps[:pool_size]):
                        ep.eid = self.allocated_pool[0] + n

                data = bytes(
                    hdr
                    + [
                        0x00,
                        alloc_status,
                        self.allocated_pool[1],
                        self.allocated_pool[0],
                    ]
                )
                await sock.send(raddr, data)

            else:
                await sock.send(
                    raddr, bytes(hdr + [0x05])
                )  # unsupported command

    async def send_control(self, sock, cmd):
        typ = cmd.MSGTYPE
        # todo: tag 0 implied
        addr = MCTPSockAddr(self.iface.net, self.eid, typ, 0x80)
        if sock.addr_ext:
            addr.set_ext(self.iface.ifindex, self.lladdr)

        key = (typ, cmd.iid)
        assert key not in self.commands

        self.commands[key] = cmd

        await sock.send(addr, cmd.to_buf())

        return await cmd.wait()


class Network:
    def __init__(self):
        self.endpoints = []
        self.mctp_socket = None

    def add_endpoint(self, endpoint):
        self.endpoints.append(endpoint)

    def lookup_endpoint(self, iface, lladdr):
        for ep in self.endpoints:
            if ep.iface == iface and ep.lladdr == lladdr:
                return ep
        return None

    # register the core mctp control socket, on which incoming requests
    # are sent to mctpd
    def register_mctp_socket(self, socket):
        assert self.mctp_socket is None
        self.mctp_socket = socket


