        prefix = 'IFLA_'
        nla_map = ((AF_MCTP, 'AF_MCTP', 'af_spec_mctp'),)

        class af_spec_mctp(netlink.nla):
            prefix = 'IFLA_MCTP_'
            nla_map = (
                ('IFLA_MCTP_UNSPEC', 'none'),
                ('IFLA_MCTP_NET', 'uint32'),
                ('IFLA_MCTP_PHYS_BINDING', 'uint8'),
            )

    class l2addr(netlink.nla_base):
        fields = [('value', 's')]


